using DistributedMonolith.Orders.Api;using DistributedMonolith.Orders.Application;using DistributedMonolith.Orders.Infrastructure;using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddDbContext<OrdersDbContext>(o=>o.UseSqlite(builder.Configuration.GetConnectionString("Database")??"Data Source=Orders.db"));builder.Services.AddHttpClient<UsersClient>(c=>c.BaseAddress=new(builder.Configuration["Services:Users"]??"http://localhost:5101"));builder.Services.AddHttpClient<ProductsClient>(c=>c.BaseAddress=new(builder.Configuration["Services:Products"]??"http://localhost:5102"));builder.Services.AddScoped<OrderService>();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();var app=builder.Build();using(var s=app.Services.CreateScope()){s.ServiceProvider.GetRequiredService<OrdersDbContext>().Database.EnsureCreated();}app.UseSwagger();app.UseSwaggerUI();app.MapOrderEndpoints();app.MapGet("/health",()=>Results.Ok());app.Run();
